// visca cliento con sesion iniciada
import React from 'react';
import { Link } from 'react-router-dom';
//estilos
import "../../components/cliente.css";//imagenes
// header y footer
import Header from '../../components/Header_c.jsx'; 
import Footer from '../../components/Footer.jsx'; 

const Cliente = () => {
    return (
        <>
        <Header />

        <main>
            <section className="buscador">
            <input type="text" placeholder="Buscar productos..." />
            <button>🔎</button>
            </section>

            <section className="hero">
            <div className="hero-texto">
                <h1>Gurama</h1>
                <h3>Confecciones y pedidos</h3>
                <p>
                ¡Crea momentos especiales con nuestros<br/> 
                <span>amigurumis y sábanas personalizadas!</span>
                </p>
            </div>
            <div className="hero-imagen">
                <img src="../imagenes/2.png" alt="Amigurumis personalizados" />
            </div>
            </section>

            <section className="promocion">
            <p>Sorprende a tus seres queridos con regalos únicos y hechos con amor</p>
            <Link to="/catalogo" className="boton-catalogo">Explora nuestro catálogo</Link>
            </section>
        </main>

        <Footer />
        </>
    );
    };

    export default Cliente;
